<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $scenarios = ["Array of objects" => [["url" => "http://test.com"]], "Array of nulls" => [null], "Array of numbers" => [123], "Array of empty arrays" => [[]]]; foreach ($scenarios as $name => $images) { echo "Testing: $name\n"; $validator = Illuminate\Support\Facades\Validator::make(["images" => $images], ["images" => "nullable|array", "images.*" => "nullable|string|url"]); if ($validator->fails()) { print_r($validator->errors()->toArray()); } else { echo "Passed!\n"; } echo "-------------------------\n"; }
